const companies = $input.all().map(i => ({
  name: i.json.name,
  ats: i.json.ats_type,
  id: i.json.ats_id
}));
const KW=["ai","ml","machine learning","genai","llm","nlp","computer vision","data scientist","mlops","ai engineer","research scientist","deep learning","generative","foundation model"];
const hasAI=t=>{const l=(t||"").toLowerCase();return KW.some(k=>l.includes(k));};
const strip=h=>(h||"").replace(/<[^>]+>/g," ").replace(/\s{2,}/g," ").trim().slice(0,3000);
const results=[];const seen=new Set();
for(const c of companies){
  try{
    let url;
    if(c.ats==="greenhouse")url="https://boards-api.greenhouse.io/v1/boards/"+c.id+"/jobs?content=true";
    else if(c.ats==="lever")url="https://api.lever.co/v0/postings/"+c.id+"?content=true";
    else url="https://api.ashbyhq.com/posting-api/job-board/"+c.id;
    const r=await fetch(url,{headers:{"User-Agent":"JobAgent/1.0"}});
    if(!r.ok)continue;
    const d=await r.json();
    let jobs=[];
    if(c.ats==="greenhouse")jobs=(d.jobs||[]).filter(j=>hasAI(j.title)).map(j=>({company:c.name,role:j.title,jd_url:j.absolute_url||"",jd_text:strip(j.content),ats_type:"greenhouse",location:(j.location&&j.location.name)||"Remote",status:"scraped"}));
    else if(c.ats==="lever")jobs=(Array.isArray(d)?d:[]).filter(j=>hasAI(j.text)).map(j=>({company:c.name,role:j.text,jd_url:j.hostedUrl||"",jd_text:strip(j.descriptionBody||j.description),ats_type:"lever",location:(j.categories&&j.categories.location)||"Remote",status:"scraped"}));
    else jobs=((d.jobPostings||[])).filter(j=>hasAI(j.title)).map(j=>({company:c.name,role:j.title,jd_url:j.externalLink||"",jd_text:strip(j.descriptionBody),ats_type:"ashby",location:(j.locationNames&&j.locationNames[0])||"Remote",status:"scraped"}));
    for(const job of jobs){if(job.jd_url&&!seen.has(job.jd_url)){seen.add(job.jd_url);results.push({json:job});}}
  }catch(e){}
}
return results.length?results:[{json:{jd_url:"",status:"scraped"}}];

// Quality Gate — drop senior / >5y-experience / thin / spam jobs BEFORE Gemini.
// Failing jobs are kept but marked status='filtered' so the scorer
// (Get Unscored Jobs = status 'scraped') never sends them to Gemini.
const SENIOR = /\b(staff|principal|lead|director|vp|vice president|head|manager)\b/i;
const SPAM = /(unpaid|commission only|mlm|pyramid)/i;
const AI_KW = ["ai","ml","machine learning","genai","llm","nlp","computer vision","data scientist","mlops","ai engineer","research scientist","deep learning","generative","foundation model","data science"];
const MIN_JD = 300;
const hasAI = t => { const l=(t||"").toLowerCase(); return AI_KW.some(k=>l.includes(k)); };
const maxYears = t => { const re=/(\d+)\s*(\+)?\s*(?:years|yrs)/gi; let m, mx=0; while((m=re.exec(t||""))!==null){ const n=parseInt(m[1],10); const eff=n+(m[2]?0.5:0); if(eff>mx) mx=eff; } return mx; };
return $input.all().map(item => {
  const j = { ...item.json };
  const title = j.role || "";
  const jd = j.jd_text || "";
  let reason = null;
  if (SENIOR.test(title)) reason = "senior-only title";
  else if (maxYears(jd) > 5) reason = "requires >5y experience";
  else if (jd.length < MIN_JD) reason = "thin description";
  else if (SPAM.test(jd) || SPAM.test(title)) reason = "spam";
  else if (!hasAI(title) && !hasAI(jd)) reason = "non-target (no AI/ML keywords)";
  if (reason) { j.status = "filtered"; j.match_justification = "Filtered: " + reason; }
  return { json: j };
});

const item = $input.first().json;
const CANDIDATE = "Jagadeesh K L — AI/ML professional. B.Tech in Artificial Intelligence & Data Science (CGPA 8.6, 2024). 1.6+ years at Cognizant as a Workday Extend Consultant (custom enterprise apps, REST integrations, orchestrations, role-based security). Data Science Intern at Shiash Info Solutions. Skills: Python, SQL, TensorFlow, PyTorch, LangChain, ChainLit, Pandas, NumPy, Matplotlib, Power BI; Machine Learning, LLMs, NLP, LSTM, CNN, RAG, time-series forecasting, vector databases, REST APIs, data analytics. Projects: Med-Doc LLM medical chatbot (90% accuracy, RAG + vector DB + ChainLit); LSTM stock-price predictor (86% accuracy); LipNet + Morse Code accessibility tool (CNN, Android). Certifications: Generative AI — LLM Foundations (Google Cloud), Workday Pro Integrations, Workday Integration Orchestration, ML Specialization & Mathematics for ML (deeplearning.ai, ongoing). Locations: Chennai or Bangalore.";
const prompt = "Score this job against the candidate profile across 6 dimensions.\n\nCANDIDATE PROFILE:\n" + CANDIDATE + "\n\nJOB (" + item.company + " — " + item.role + "):\n" + (item.jd_text||"").slice(0,1500) + "\n\nReturn ONLY valid JSON (no markdown). Each dimension score is an integer 0-100 with a one-line reason:\n{\"dimensions\":{\"stack_fit\":{\"score\":0,\"reason\":\"\"},\"seniority\":{\"score\":0,\"reason\":\"\"},\"location\":{\"score\":0,\"reason\":\"\"},\"compensation\":{\"score\":0,\"reason\":\"\"},\"evidence\":{\"score\":0,\"reason\":\"\"},\"mission\":{\"score\":0,\"reason\":\"\"}},\"matched_skills\":[],\"missing_skills\":[]}";
return [{json:{
  _job_id: item.id,
  gemini_request:{
    systemInstruction:{parts:[{text:"You are an expert ATS resume analyst for AI/ML roles. Return valid JSON only, no markdown fences."}]},
    contents:[{role:"user",parts:[{text:prompt}]}],
    generationConfig:{temperature:0.1,maxOutputTokens:700,responseMimeType:"application/json"}
  }
}}];

const resp = $input.first().json;
const text = (resp.candidates&&resp.candidates[0]&&resp.candidates[0].content&&resp.candidates[0].content.parts&&resp.candidates[0].content.parts[0]&&resp.candidates[0].content.parts[0].text)||'{}';
const clean = text.replace(/```json[\s\S]*?```|```[\s\S]*?```/g,'').replace(/```/g,'').trim();
const WEIGHTS = {stack_fit:0.30,evidence:0.20,seniority:0.20,mission:0.15,location:0.10,compensation:0.05};
const DIMS = ["stack_fit","seniority","location","compensation","evidence","mission"];
const clamp = n => { n=Number(n); if(!isFinite(n)) return 0; return Math.max(0,Math.min(100,Math.round(n))); };
try {
  const p = JSON.parse(clean);
  const d = p.dimensions || {};
  const breakdown = {};
  let overall = 0;
  for (const k of DIMS) {
    const score = clamp(d[k] && d[k].score);
    const reason = (d[k] && typeof d[k].reason === 'string') ? d[k].reason : '';
    breakdown[k] = { score, reason };
    overall += (WEIGHTS[k]||0) * score;
  }
  overall = Math.round(overall);
  const matched = overall >= 60;
  const justification = DIMS.map(k=>({k,r:breakdown[k].reason})).filter(x=>x.r).map(x=>x.k.replace('_',' ')+': '+x.r).join('\n');
  return [{json:{
    match_score: overall,
    score_breakdown: breakdown,
    matched_skills: p.matched_skills||[],
    missing_skills: p.missing_skills||[],
    match_justification: matched ? justification : ('Below threshold ('+overall+')'),
    status: matched ? 'matched' : 'filtered'
  }}];
} catch(e) {
  return [{json:{match_score:0,score_breakdown:null,match_justification:'Parse failed',missing_skills:[],matched_skills:[],status:'scraped'}}];
}

return [
